using System.Text.Json;
using Google.Protobuf;
using FantasyCard.Contracts.Http;
using FantasyCard.Contracts.Realtime;
using H = FantasyCard.Contracts.Http.V1;
using W = FantasyCard.Contracts.Wire.Realtime.V1;

int passed = 0;
void Check(bool condition, string name) { if (!condition) throw new Exception(name); Console.WriteLine("PASS " + name); passed++; }
void Reject(Action action, string name) { try { action(); } catch (Exception e) when (e is InvalidDataException or InvalidProtocolBufferException or FormatException or OverflowException) { Check(true,name); return; } throw new Exception("Expected rejection: " + name); }
const string id = "11111111-2222-3333-4444-555555555555";
var vectors = new List<object>();
void Vector(string name, string message, IMessage value) => vectors.Add(new { name, message, hex = Convert.ToHexString(value.ToByteArray()).ToLowerInvariant() });
Parallel.For(0, 64, index =>
{
    var walletRoute = HttpProtocolRegistry.Find("GET", "/api/v1/economy/wallet")!;
    var encoded = HttpDtoMapper.EncodeResponse(walletRoute, new FantasyCard.Contracts.Progression.WalletResponse(long.MaxValue - index, index));
    var decoded = (FantasyCard.Contracts.Progression.WalletResponse)HttpDtoMapper.ToDto(H.WalletResponse.Parser.ParseFrom(encoded), typeof(FantasyCard.Contracts.Progression.WalletResponse));
    if (decoded.Gold != long.MaxValue - index || decoded.Diamond != index) throw new Exception("Concurrent mapper value contamination");
});
Check(true, "concurrent cold metadata initialization isolates request values");
var quoteAbsent = new FantasyCard.Contracts.Progression.EnhancementQuoteResponse("armor", 0, null, long.MaxValue, 0, 0, null, 0, 0, false, null);
var quoteWire = (H.EnhancementQuoteResponse)HttpDtoMapper.FromDto(H.EnhancementQuoteResponse.Descriptor, quoteAbsent);
Check(!quoteWire.HasNextLevel && !quoteWire.HasMaterialQuality && quoteWire.ExpectedVersion == long.MaxValue, "compiled scalar bindings preserve nullable absence");
var quoteZero = (H.EnhancementQuoteResponse)HttpDtoMapper.FromDto(H.EnhancementQuoteResponse.Descriptor, quoteAbsent with { NextLevel = 0, MaterialQuality = "", CanEnhance = true });
Check(quoteZero.HasNextLevel && quoteZero.NextLevel == 0 && quoteZero.HasMaterialQuality && quoteZero.MaterialQuality == "" && quoteZero.CanEnhance, "compiled scalar bindings preserve optional zero empty and bool");
var mailAliases = new FantasyCard.Contracts.Mail.MailItemResponse(Guid.Parse(id), "t", "b", "s", DateTimeOffset.UnixEpoch, null, true, false, []);
var mailWire = (H.MailItemResponse)HttpDtoMapper.FromDto(H.MailItemResponse.Descriptor, mailAliases);
Check(mailWire.Read && !mailWire.Claimed, "compiled mail alias getter and setter");
var route = HttpProtocolRegistry.Find("POST", "/api/v1/auth/local")!;
var login = new H.LocalSignInRequest { DeviceId = "local-test-001", DisplayName = "山海客" };
var dto = (FantasyCard.Contracts.Identity.LocalSignInRequest)HttpDtoMapper.DecodeRequest(route, login.ToByteArray(), typeof(FantasyCard.Contracts.Identity.LocalSignInRequest));
Check(dto.DisplayName == "山海客" && dto.DeviceId == "local-test-001", "official protobuf to login DTO UTF8");
Vector("local-login", "LocalSignInRequest", login);
var player = new FantasyCard.Contracts.Players.PlayerProfileResponse(Guid.Parse(id), "山海客", null, long.MaxValue, DateTimeOffset.UnixEpoch, DateTimeOffset.UnixEpoch);
var profile = H.PlayerProfileResponse.Parser.ParseFrom(HttpDtoMapper.EncodeResponse(HttpProtocolRegistry.Find("GET","/api/v1/players/me")!, player));
Check(profile.Version == long.MaxValue && !profile.HasSelectedClass, "profile int64 boundary and absent enum");
Vector("profile-int64", "PlayerProfileResponse", profile);
var req = new H.UpdatePlayerProfileRequest { ExpectedVersion = long.MinValue, DisplayName = "", SelectedClass = "Mage" };
var update = (FantasyCard.Contracts.Players.UpdatePlayerProfileRequest)HttpDtoMapper.DecodeRequest(HttpProtocolRegistry.Find("PUT","/api/v1/players/me")!,req.ToByteArray(),typeof(FantasyCard.Contracts.Players.UpdatePlayerProfileRequest));
Check(update.ExpectedVersion == long.MinValue && update.DisplayName == "" && update.SelectedClass == FantasyCard.Contracts.Players.HeroClassDto.Mage,"negative int64 and optional empty string");
Vector("profile-update-min-int64", "UpdatePlayerProfileRequest", req);
var absent = new H.UpdatePlayerProfileRequest();
var absentDto = (FantasyCard.Contracts.Players.UpdatePlayerProfileRequest)HttpDtoMapper.DecodeRequest(HttpProtocolRegistry.Find("PUT","/api/v1/players/me")!,absent.ToByteArray(),typeof(FantasyCard.Contracts.Players.UpdatePlayerProfileRequest));
Check(absentDto.DisplayName is null && absentDto.SelectedClass is null,"optional absent preserved");
var purchase = new H.PurchaseShopRequest { ProductId = "p" };
var purchaseDto = (FantasyCard.Contracts.Progression.PurchaseShopRequest)HttpDtoMapper.DecodeRequest(HttpProtocolRegistry.Find("POST","/api/v1/shop/purchases")!,purchase.ToByteArray(),typeof(FantasyCard.Contracts.Progression.PurchaseShopRequest));
Check(purchaseDto.Quantity == 1,"omitted request default preserves JSON semantics");
var prep = new H.CreatePreparationRequest { HeroClass="Mage", BackpackTier="Free", DeckVersion=long.MaxValue };
prep.EquipmentIds.Add(new[]{"",id,"","",""}); prep.SafeSlotIndexes.Add(new[]{0,2,4});
var prepDto = (FantasyCard.Contracts.Matchmaking.CreatePreparationRequest)HttpDtoMapper.DecodeRequest(HttpProtocolRegistry.Find("POST","/api/v1/preparations")!,prep.ToByteArray(),typeof(FantasyCard.Contracts.Matchmaking.CreatePreparationRequest));
Check(prepDto.EquipmentIds![0] is null && prepDto.EquipmentIds[1] == Guid.Parse(id) && prepDto.SafeSlotIndexes!.SequenceEqual(new[]{0,2,4}),"packed repeated and nullable equipment slots");
Vector("preparation-packed", "CreatePreparationRequest", prep);
var unknown = login.ToByteArray().Concat(new byte[]{0xa0,0x06,0x01}).ToArray();
Check(((FantasyCard.Contracts.Identity.LocalSignInRequest)HttpDtoMapper.DecodeRequest(route,unknown,typeof(FantasyCard.Contracts.Identity.LocalSignInRequest))).DisplayName == dto.DisplayName,"unknown field ignored");
Reject(()=>HttpDtoMapper.DecodeRequest(route,new byte[]{0x12,0x7f,0x01},typeof(FantasyCard.Contracts.Identity.LocalSignInRequest)),"truncated request rejected");
Reject(()=>HttpDtoMapper.DecodeRequest(route,new byte[HttpProtocolRegistry.MaximumBodyBytes+1],typeof(FantasyCard.Contracts.Identity.LocalSignInRequest)),"HTTP body limit");
Reject(()=>HttpDtoMapper.EncodeResponse(HttpProtocolRegistry.Find("GET","/api/v1/players/me")!,player with { DisplayName = new string('x',HttpProtocolRegistry.MaximumStringBytes+1) }),"HTTP string limit");
var shop = new FantasyCard.Contracts.Progression.ShopProductResponse("p","Cards",long.MaxValue,1,0,"{\"cardId\":\"M-1\",\"count\":1,\"amount\":9223372036854775807}");
var shopWire = (H.ShopProductResponse)HttpDtoMapper.FromDto(H.ShopProductResponse.Descriptor,shop);
Check(shopWire.Payload.CardId == "M-1" && shopWire.Payload.Amount == long.MaxValue,"shop persisted JSON translated to typed fields without float");
Vector("shop-product-typed", "ShopProductResponse", shopWire);
var wallet = new FantasyCard.Contracts.Progression.WalletResponse(long.MaxValue,0);
Check(H.WalletResponse.Parser.ParseFrom(HttpDtoMapper.EncodeResponse(HttpProtocolRegistry.Find("GET","/api/v1/economy/wallet")!,wallet)).Gold == long.MaxValue,"wallet int64 exact");
var resumed = new ClientCommand("session.resume","r",0,new SessionResumeCommandPayload(long.MaxValue,Guid.Parse(id),long.MinValue));
var legacyClient = RealtimeProtobufCodec.EncodeClient(resumed);
var officialEnvelope = W.ClientEnvelope.Parser.ParseFrom(legacyClient);
var officialResume = W.SessionResumeCommand.Parser.ParseFrom(officialEnvelope.Payload);
Check(officialEnvelope.HasExpectedRevision && officialEnvelope.ExpectedRevision == 0 && officialResume.RoomRevision == long.MinValue,"legacy realtime encoder official decode optional zero and min int64");
Check(((SessionResumeCommandPayload)RealtimeProtobufCodec.DecodeClient(officialEnvelope.ToByteArray()).Payload!).LastSequence == long.MaxValue,"official realtime encode legacy decode");
Vector("resume-envelope", "ClientEnvelope", officialEnvelope);
var mapEvent = new ServerEvent("map.player_count","trace",new MapPlayerCountEventPayload(4),"e",7,DateTimeOffset.UnixEpoch);
var mapEnvelope = W.ServerEnvelope.Parser.ParseFrom(RealtimeProtobufCodec.EncodeServer(mapEvent));
Check(W.MapPlayerCountEvent.Parser.ParseFrom(mapEnvelope.Payload).PlayerCount == 4,"map count drift fixed");
Vector("map-count", "MapPlayerCountEvent", W.MapPlayerCountEvent.Parser.ParseFrom(mapEnvelope.Payload));
var combo = new W.BattleComboResolvedEvent { BattleId=id,AttackerId=id,TargetId="m",ResonanceMultiplier="1.25",ConflictPairCount=2,ConflictCancellation="0.5" };
var comboEnvelope = new W.ServerEnvelope { ProtocolVersion=1,Type="battle.combo_resolved",Payload=combo.ToByteString() };
var legacyCombo = (BattleComboResolvedEventPayload)RealtimeProtobufCodec.DecodeServer(comboEnvelope.ToByteArray()).Payload!;
Check(legacyCombo.ResonanceMultiplier == "1.25" && legacyCombo.ConflictPairCount == 2 && legacyCombo.ConflictCancellation == "0.5","combo tags 24-26 official to legacy");
Vector("combo-fields-24-26", "BattleComboResolvedEvent", combo);
var roomPlayer = new W.RoomPlayer { PlayerId=id }; roomPlayer.SafeSlotIndexes.Add(new[]{0,2,4});
var snapshot = new W.RoomSnapshotEvent { RoomId=id,Player=roomPlayer,MapPlayerCount=4 };
var snapshotEnvelope = new W.ServerEnvelope { ProtocolVersion=1,Type="room.snapshot",Payload=snapshot.ToByteString() };
var legacySnapshot = (RoomSnapshotEventPayload)RealtimeProtobufCodec.DecodeServer(snapshotEnvelope.ToByteArray()).Payload!;
Check(legacySnapshot.Player.SafeSlotIndexes!.SequenceEqual(new[]{0,2,4}) && legacySnapshot.MapPlayerCount==4,"packed snapshot and tag16 official to legacy");
// Alternate packed and unpacked occurrences in wire order: 4,1,2,3.
var mixedPlayerBytes = new W.RoomPlayer{PlayerId=id}.ToByteArray().Concat(new byte[]{0x5a,1,4,0x58,1,0x5a,1,2,0x58,3}).ToArray();
var mixedPlayer = W.RoomPlayer.Parser.ParseFrom(mixedPlayerBytes);
// Retain mixed bytes inside raw nested message; official reserialization would normalize to packed.
var rawSnapshot = new W.RoomSnapshotEvent{RoomId=id}.ToByteArray().Concat(new byte[]{0x4a,(byte)mixedPlayerBytes.Length}).Concat(mixedPlayerBytes).ToArray();
snapshotEnvelope.Payload=ByteString.CopyFrom(rawSnapshot);
var mixedLegacy = (RoomSnapshotEventPayload)RealtimeProtobufCodec.DecodeServer(snapshotEnvelope.ToByteArray()).Payload!;
Check(mixedLegacy.Player.SafeSlotIndexes!.SequenceEqual(mixedPlayer.SafeSlotIndexes),"mixed packed unpacked preserves order");
Reject(()=>RealtimeProtobufCodec.DecodeClient(new byte[]{8,0xff,0xff,0xff,0xff,0xff,0xff,0xff,0xff,0xff,2}),"overflow varint rejected");
Reject(()=>RealtimeProtobufCodec.DecodeClient(new byte[]{0}),"zero tag rejected");
Check(HttpProtocolRegistry.Endpoints.Count==46 && HttpProtocolRegistry.Find("DELETE","/api/v1/mail/read")!.Response=="MailDeleteResponse","registry coverage and literal priority");
if(args.Length>0) File.WriteAllText(args[0],JsonSerializer.Serialize(vectors,new JsonSerializerOptions{WriteIndented=true})+"\n");
